document.addEventListener("DOMContentLoaded",async e=>{await checkLogin()||(window.location.href="/login");var a=new URLSearchParams(window.location.search);let t=a.get("target")||"all";!async function a(n){try{var e=await(await fetch(BASE_URL+(`/api/recordlist?target=${t}&page=${n}&cookie=`+getcookie()))).json();if("Y"!==e.status)console.error("Failed to load submissions:",e.error);else{let t=document.getElementById("submissions");t.innerHTML="",JSON.parse(e.recordlist).forEach(e=>{var a=document.createElement("div");a.className="submission",a.innerHTML=`<a href="/record/${e}">提交记录 #${e}</a>`,t.appendChild(a)});var o=document.getElementById("pagination"),r=(o.innerHTML="",e.page);for(let e=Math.max(1,n-2);e<=r&&e<=n+2;e++){var i=document.createElement("a");e===n?i.style.background="rgba(78,161,255,.24)":i.href="/record/list?page="+e,i.textContent=e,i.onclick=()=>a(e),o.appendChild(i)}}}catch(e){console.error("Error loading submissions:",e)}}(parseInt(a.get("page"),10)||1)});